import { createRequire } from "node:module";
import path from "node:path";
import { runtimePackages } from "./verify-standalone.mjs";

// Run in the builder, where pnpm's app-level links and their targets are available.
const app = "apps/webapp";
const require = createRequire(path.resolve(app, "package.json"));
const { nodeFileTrace } = require("next/dist/compiled/@vercel/nft");

// Pino starts this transport in a separate worker. Trace its private dependencies
// independently of the server chunks generated by Turbopack.
const { fileList } = await nodeFileTrace([require.resolve("pino-opentelemetry-transport")], {
	base: process.cwd(),
	processCwd: path.resolve(app),
});

// Next traces its own links and Turbopack's hashed externals. Restore the app's
// pnpm links so Node can also resolve these packages by their original names.
for (const name of runtimePackages) {
	fileList.add(path.join(app, "node_modules", name));
}
process.stdout.write([...fileList].join("\n") + "\n");
